namespace Strata.Domain.Media;

/// <summary>Opaque blob storage for uploaded files. Keys are generated by the storage, never by users.</summary>
public interface IFileStorage
{
    Task<string> SaveAsync(Stream content, string extension, CancellationToken cancellationToken);

    /// <summary>Opens a stored file for reading, or returns null when the key does not exist.</summary>
    Task<Stream?> OpenReadAsync(string key, CancellationToken cancellationToken);
}
